<?php
$uid = (int)$u['id']; $m = row('SELECT * FROM merchants WHERE user_id=?', [$uid]); $mid = (int)$m['id']; $tab = in_array($_GET['tab'] ?? '', ['checkout', 'tokens', 'offline'], true) ? $_GET['tab'] : 'checkout';
handle('m_profile', function () use ($mid) { q('UPDATE merchants SET business_name=?, category=? WHERE id=?', [mb_substr(trim((string)$_POST['name']), 0, 120) ?: 'Shop', in_array($_POST['category'], ['shopping', 'food', 'services', 'education', 'entertainment', 'gaming'], true) ? $_POST['category'] : 'shopping', $mid]); return 'Saved.'; });
handle('m_checkout', function () use ($mid) { $c = Pay::createCheckout($mid, (string)$_POST['amount'], (string)($_POST['note'] ?? '')); flash('ok', 'Checkout created. Show the QR code to the customer.'); redirect(url('merchant', ['tab' => 'checkout', 'ref' => $c['ref']])); });
handle('m_cancel', function () use ($mid) { q("UPDATE checkout_sessions SET status='cancelled' WHERE ref=? AND merchant_id=? AND status='open'", [preg_replace('/\W/', '', (string)$_POST['ref']), $mid]); return 'Checkout cancelled.'; });
handle('m_charge', function () use ($uid) { $r = Tokens::charge($uid, trim((string)$_POST['token']), cents($_POST['amount'] ?? ''), idem_key()); if ($r['status'] === 'approved') return 'Charge approved. Reference ' . $r['ref']; throw new AppError('Charge declined: ' . $r['reason']); });
handle('m_queue', function () use ($uid) { Offline::queue($uid, (string)$_POST['token']); return 'Token stored in the offline queue. It is NOT settled until you sync.'; });
handle('m_sync', function () use ($uid) { $r = Offline::sync($uid); return "Sync finished: {$r['settled']} settled, {$r['rejected']} rejected."; });
$sum = row("SELECT COUNT(*) n, COALESCE(SUM(t.amount),0) gross, COALESCE(SUM(t.fee),0) fees FROM transactions t JOIN wallets w ON w.id=t.to_wallet_id WHERE w.user_id=? AND t.type IN ('merchant_payment','token_payment','offline_payment') AND t.status='completed'", [$uid]);
$tabs = '<div class="tabs">'; foreach (['checkout' => 'QR checkout', 'tokens' => 'Token charges (simulation)', 'offline' => 'Offline queue'] as $k => $l) $tabs .= '<a href="' . e(url('merchant', ['tab' => $k])) . '"' . ($tab === $k ? ' aria-current="page"' : '') . '>' . e($l) . '</a>'; $tabs .= '</div>';
echo page_head($m['business_name'], 'Merchant workspace: accept payments, review sales and manage fees.') . '<div class="grid g4" style="margin-bottom:16px">' . card('Sales', '<div class="stat sm">' . (int)$sum['n'] . '</div>') . card('Gross', '<div class="stat sm">' . mny($sum['gross']) . '</div>') . card('Fees paid', '<div class="stat sm">' . mny($sum['fees']) . '</div><p class="hint">' . e(setting('merchant_fee_percent')) . '% per sale</p>') . card('Net received', '<div class="stat sm pos">' . mny(dec(cents($sum['gross']) - cents($sum['fees']))) . '</div>') . '</div>' . $tabs;
if ($tab === 'checkout') {
  $ref = preg_replace('/\W/', '', (string)($_GET['ref'] ?? '')); $cs = $ref ? row('SELECT * FROM checkout_sessions WHERE ref=? AND merchant_id=?', [$ref, $mid]) : null; $qr = '';
  if ($cs) { $link = (isset($_SERVER['HTTPS']) ? 'https' : 'http') . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . rtrim(dirname($_SERVER['SCRIPT_NAME']), '/') . '/' . url('checkout', ['ref' => $cs['ref']]); $qr = card('Customer QR (simulated checkout)', '<div class="qr" data-qr="' . e($link) . '"></div><p><strong>' . mny($cs['amount']) . '</strong> ' . badge($cs['status']) . '</p><p class="hint">Expires ' . e(fdate($cs['expires_at'])) . '. The link opens the Auvryon confirmation screen for a logged-in customer.</p><input id="lnk" value="' . e($link) . '" readonly><p style="margin-top:8px"><button type="button" class="btn secondary sm" data-copy="lnk">Copy link</button></p>'); }
  $list = rows('SELECT * FROM checkout_sessions WHERE merchant_id=? ORDER BY id DESC LIMIT 12', [$mid]); $rows = [];
  foreach ($list as $c) { if ($c['status'] === 'open' && strtotime($c['expires_at']) < time()) $c['status'] = 'expired'; $rows[] = [e(fdate($c['created_at'])), e($c['note']), mny($c['amount']), badge($c['status']), '<a href="' . e(url('merchant', ['tab' => 'checkout', 'ref' => $c['ref']])) . '">Open</a>' . ($c['status'] === 'open' ? ' ' . form_start('m_cancel', 'class="inline"') . '<input type="hidden" name="ref" value="' . e($c['ref']) . '">' . btn('Cancel', 'secondary sm') . '</form>' : '')]; }
  echo '<div class="grid g2"><div class="grid">' . card('New checkout', form_start('m_checkout') . field('Amount (BDT)', 'amount', 'text', '', 'required inputmode="decimal"') . field('Note', 'note', 'text', '', 'maxlength="200"') . btn('Create QR checkout') . '</form>') . $qr . '</div><div class="grid">' . card('Recent checkouts', tbl(['When', 'Note', ['Amount', 'num'], 'Status', ''], $rows, 'No checkouts yet.')) . card('Business profile', form_start('m_profile') . field('Business name', 'name', 'text', $m['business_name'], 'required') . select('Category', 'category', ['shopping' => 'Shopping', 'food' => 'Food', 'services' => 'Services', 'education' => 'Education', 'entertainment' => 'Entertainment', 'gaming' => 'Gaming'], $m['category']) . btn('Save', 'secondary') . '</form>') . '</div></div>';
} elseif ($tab === 'tokens') {
  $cl = rows('SELECT c.*, t.token_last4, u.name FROM token_charges c JOIN virtual_tokens t ON t.id=c.token_id JOIN users u ON u.id=t.user_id WHERE t.merchant_id=? ORDER BY c.id DESC LIMIT 12', [$mid]); $rows = [];
  foreach ($cl as $c) $rows[] = [e(fdate($c['created_at'])), '...' . e($c['token_last4']), mny($c['amount']), badge($c['status']), e($c['reason'])];
  echo '<div class="grid g2">' . card('Simulate a merchant-initiated charge', '<div class="alert info">SIMULATION: this stands in for your billing system charging a customer\'s merchant-specific virtual token. Paused, cancelled or over-limit tokens are declined.</div>' . form_start('m_charge') . field('Customer virtual token', 'token', 'text', '', 'required placeholder="avt_..." autocomplete="off"') . field('Amount (BDT)', 'amount', 'text', '', 'required inputmode="decimal"') . btn('Charge token') . '</form>') . card('Token charge log', tbl(['When', 'Token', ['Amount', 'num'], 'Result', 'Reason'], $rows, 'No token charges yet.')) . '</div>';
} else {
  $ql = rows('SELECT * FROM offline_queue WHERE merchant_user_id=? ORDER BY id DESC LIMIT 15', [$uid]); $rows = [];
  foreach ($ql as $x) $rows[] = [e(fdate($x['queued_at'])), badge($x['status']), e($x['message']), $x['txn_id'] ? ref_link((string)val('SELECT ref FROM transactions WHERE id=?', [$x['txn_id']])) : '-'];
  echo '<div class="grid g2">' . card('Offline queue (simulated)', '<div class="alert warn">Queued payments are <strong>not settled</strong>. Settlement happens only when you sync, after balance, expiry and replay checks.</div>' . form_start('m_queue') . '<div class="field"><label for="tk">Customer offline token</label><textarea id="tk" name="token" rows="3" required class="mono" placeholder="Paste the token from the customer\'s Offline QR page"></textarea></div>' . btn('Add to offline queue', 'secondary') . '</form><hr>' . form_start('m_sync') . btn('Sync queue now') . '</form>') . card('Queue status', tbl(['Queued', 'Status', 'Message', 'Txn'], $rows, 'The queue is empty.')) . '</div>';
}
